import{z as A,x as E,o as r,c as d,q as t,j as i,D as e,d as n,s,S as p,b as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"电路复杂性","description":"","frontmatter":{"title":"电路复杂性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/circuit-complexity.md","filePath":"cs/circuit-complexity.md","lastUpdated":1791413859000}'),P={name:"cs/circuit-complexity.md"};function m(B,a,c,h,C,T){const l=E("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="电路复杂性" tabindex="-1">电路复杂性 <a class="header-anchor" href="#电路复杂性" aria-label="Permalink to &quot;电路复杂性&quot;">​</a></h1><div class="epigraph"><p>电路族 $\\{C_n\\}$ 是非均匀计算：每个长度一张图。P/poly 包含 P，也包含不可判定的稀疏语言；下界极难。</p><footer>—— 据 Shannon；Savage；Arora and Barak 整理</footer></div><p>上一课<a href="/cs/pcp-inapproximability">PCP</a> 仍是均匀 TM。缺口是<strong>电路</strong>：有限函数的有向无环图，门是与或非。<a href="/cs/boolean-algebra">布尔代数</a> 给了门的公理；组成课有组合网。本课把族 \\(\\{C_n\\}\\)、规模、深度、P/poly 收成复杂类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>均匀：一台 TM 管所有 \\(n\\)。非均匀：允许 \\(C_n\\) 随 \\(n\\) 任意换，只要 \\(|C_n|\\) 有界（如多项式）。<span class="marginnote">术语翻译：电路族 \\(\\{C_n\\}\\) 就是「每种输入长度发一张专属电路」——\\(C_1\\) 管 1 位输入、\\(C_2\\) 管 2 位输入，各不相干；「均匀」则要求一个算法能生成所有这些电路。非均匀模型比算法松得多，这正是它「可能作弊」的根源。</span>P/poly：多项式规模电路族。\\(P\\subseteq P/poly\\)。顾问串：多项式建议，带此建议的 \\(P\\) 类就是 \\(P/\\mathrm{poly}\\)。若 \\(\\mathrm{NP}\\subseteq P/poly\\) 则 PH 塌缩（Karp–Lipton），故 NPC 问题被信不在 P/poly。Shannon：大多数函数需要指数规模电路——存在性，不给出 SAT 的下界。</p><p>AC\\(^0\\)、NC：常数深度 / 多对数深度，并行直觉。Ajtai / Furst–Saxe–Sipser / Razborov–Smolensky 对 AC\\(^0\\) 的奇偶下界，点名：少数成功的下界。</p><h3 id="非均匀可以「作弊」" tabindex="-1">非均匀可以「作弊」 <a class="header-anchor" href="#非均匀可以「作弊」" aria-label="Permalink to &quot;非均匀可以「作弊」&quot;">​</a></h3><p>不可判定的一元语言可有空电路或常数电路。故 P/poly 不是「可行」的同义词。均匀性（TM 输出电路描述）才回到算法。</p><p><span class="marginnote">Shannon 计电路数目。Savage 定理：时间 \\(T\\) 的 TM 变规模 \\(O(T^2)\\) 电路（Cook–Levin 表竖过来）。Arora–Barak 第 6 章。本课不证自然证明障碍全文，点名 Razborov–Rudich。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从 TM 运行表得到电路：每格一个门。反之，多项式电路不自动给出均匀算法。画 P / P/poly / EXP 的包含。深度与规模是两个轴：公式是树，电路可共享子结果。</p>',11)),(r(),i(p,null,{default:e(()=>[s(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TM%5B%22%E5%9D%87%E5%8C%80%20TM%22%5D%20--%3E%20TAB%5B%22%E8%AE%A1%E7%AE%97%E8%A1%A8%22%5D%0A%20%20TAB%20--%3E%20CK%5B%22%E7%94%B5%E8%B7%AF%20C_n%22%5D%0A%20%20ADV%5B%22%E9%A1%BE%E9%97%AE%E4%B8%B2%22%5D%20--%3E%20PPOLY%5B%22P%2Fpoly%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[n("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"下界难：自然证明说，某些「建设性」的组合性质若能区分硬函数，也会击穿伪随机，从而击穿单向函数假设。故电路下界与后课密码学咬合。本课只要这句警告，避免把「门数」当成已证的 SAT 指数下界。",-1)),a[5]||(a[5]=o("p",null,"为什么学界相信 NP 不在 P/poly，推理链是一条塌缩警告：",-1)),(r(),i(p,null,{default:e(()=>[s(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASS%5B%22%E5%81%87%E8%AE%BE%3A%20NP%20%E5%85%A8%E9%83%A8%E8%90%BD%E5%9C%A8%20P%2Fpoly%22%5D%20--%3E%20KL%5B%22Karp-Lipton%20%E5%AE%9A%E7%90%86%E8%A7%A6%E5%8F%91%22%5D%0A%20%20KL%20--%3E%20COLL%5B%22%E5%A4%9A%E9%A1%B9%E5%BC%8F%E5%B1%82%E7%BA%A7%20PH%20%E5%A1%8C%E7%BC%A9%22%5D%0A%20%20COLL%20--%3E%20CONC%5B%22%E4%B8%8E%E5%88%86%E5%B1%82%E4%BF%A1%E5%BF%B5%E5%86%B2%E7%AA%81%2C%20%E6%95%85%20NPC%20%E8%A2%AB%E4%BF%A1%E9%9C%80%E8%A6%81%E8%B6%85%E5%A4%9A%E9%A1%B9%E5%BC%8F%E9%97%A8%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>Savage：时间 \\(T\\) 的多带 TM 变成规模 \\(O(T^2)\\) 电路。反之，多项式电路族不必有均匀生成器。AC\\(^0\\) 奇偶下界是少数「显式函数需要超多项式规模 / 超常数深度」的定理。自然证明障碍解释其后进展慢：能区分随机函数的组合性质太强，会破坏伪随机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Razborov–Smolensky，不引入 ACC。不把机器学习的「神经网络」当电路类。后课默认：多项式电路 = P/poly；均匀 vs 非均匀要声明。下一课换参数：FPT。</p><p>非均匀允许每个 \\(n\\) 换一张电路，甚至编码不可判定的稀疏语言。均匀性（TM 输出电路描述）才回到算法。Karp–Lipton 把「NP 有多项式电路」连到 PH 塌缩，故 NPC 被信不在 \\(P/poly\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>电路族是非均匀计算；P/poly 含 P，也可含不可行对象。</li><li>TM 时间给出电路规模上界；显式下界稀缺。<span class="marginnote">数字实例：规模就是门数。\\(n\\) 位输入若按真值表硬造电路要约 \\(2^n\\) 行，\\(n=100\\) 时就是 \\(10^{30}\\) 量级，宇宙原子都不够数；而「多项式规模」如 \\(n^3\\)，同样 \\(n=100\\) 只需 \\(10^6\\) 个门。规模指数是电路世界里的「可不可行」分界线。</span></li><li>Karp–Lipton：NP 若在 P/poly 则 PH 塌。</li><li>后课谈均匀 vs 非均匀，先声明电路族怎么生成。</li><li>出处：Shannon；Savage；Arora and Barak。</li></ul>',6))])}const S=A(P,[["render",m]]);export{_ as __pageData,S as default};
